{
  "name": "App Ảnh Doanh Nhân",
  "description": "Tạo ảnh chân dung doanh nhân sang trọng, đẳng cấp và nghệ thuật với 100+ concept thế giới.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useState, useCallback } from 'react';
import ImageUploader from './components/ImageUploader';
import ConceptSelector from './components/ConceptSelector';
import CustomPromptInput from './components/CustomPromptInput';
import ResultGrid from './components/ResultGrid';
import LoadingModal from './components/LoadingModal';
import { CONCEPTS, LOADING_QUOTES } from './constants';
import { generatePortraits } from './services/geminiService';
import type { GeneratedImage } from './types';

const App: React.FC = () => {
  // State management
  const [uploadedImage, setUploadedImage] = useState<{ file: File, preview: string } | null>(null);
  const [selectedConcept, setSelectedConcept] = useState<string | null>(CONCEPTS[0].key);
  const [customPrompt, setCustomPrompt] = useState<string>('');
  const [isFaceLockEnabled, setIsFaceLockEnabled] = useState<boolean>(true);
  const [withFlowers, setWithFlowers] = useState<boolean>(false);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [finalPrompt, setFinalPrompt] = useState<string>('');


  // Handlers
  const handleImageUpload = (file: File, previewUrl: string) => {
    setUploadedImage({ file, preview: previewUrl });
    setError(null); // Clear previous errors on new upload
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const result = reader.result as string;
        // remove data:image/jpeg;base64,
        resolve(result.split(',')[1]);
      };
      reader.onerror = error => reject(error);
    });
  };

  const handleGenerate = useCallback(async () => {
    if (!uploadedImage) {
      setError('Vui lòng tải ảnh gốc lên.');
      return;
    }
    if (!selectedConcept) {
      setError('Vui lòng chọn một concept.');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGeneratedImages([]); // Clear previous images

    try {
      const conceptPrompt = CONCEPTS.find(c => c.key === selectedConcept)?.prompt || '';
      const fullPrompt = `${conceptPrompt}${customPrompt ? `, ${customPrompt}` : ''}.`;
      setFinalPrompt(fullPrompt); // Save the prompt for the modal

      const imageBase64 = await fileToBase64(uploadedImage.file);

      const params = {
        prompt: fullPrompt,
        negativePrompt: 'blurry, grainy, deformed, distorted, ugly, disfigured, poorly drawn, extra limbs, bad anatomy, mutated, watermark, signature, text, multiple people, low quality, cartoon, anime',
        aspectRatio: '9:16' as const,
        imageBase64,
        mimeType: uploadedImage.file.type,
        numberOfImages: 2 as const,
        isFaceLockEnabled: isFaceLockEnabled,
        withFlowers: withFlowers,
      };

      const results = await generatePortraits(params);

      setGeneratedImages(results);


    } catch (err: any) {
      setError(err.message || 'Đã xảy ra lỗi không mong muốn.');
    } finally {
      setIsLoading(false);
    }
  }, [uploadedImage, selectedConcept, customPrompt, isFaceLockEnabled, withFlowers]);

  const isGenerateDisabled = isLoading || !uploadedImage || !selectedConcept;

  return (
    <div className="min-h-screen bg-pink-50 text-zinc-900">
      <LoadingModal isOpen={isLoading} quotes={LOADING_QUOTES} />
      <header className="text-center pt-8 pb-4">
        <h1 className="text-5xl font-bold text-orange-600 tracking-wider drop-shadow-sm">APP ẢNH DOANH NHÂN</h1>
        <p className="text-pink-600 mt-2 font-medium">Chân dung đẳng cấp - Khẳng định vị thế</p>
      </header>
      <main className="max-w-7xl mx-auto p-4 md:p-8 grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left Column: Controls */}
        <div className="lg:col-span-1 flex flex-col gap-6">
          <ImageUploader 
            onImageUpload={handleImageUpload} 
            preview={uploadedImage?.preview || null} 
            isFaceLockEnabled={isFaceLockEnabled}
            onToggleFaceLock={setIsFaceLockEnabled}
            withFlowers={withFlowers}
            onToggleWithFlowers={setWithFlowers}
          />
          <ConceptSelector selectedConcept={selectedConcept} onSelectConcept={setSelectedConcept} />
          <CustomPromptInput customPrompt={customPrompt} onCustomPromptChange={setCustomPrompt} />

          <div className="mt-2">
            {error && <p className="text-red-500 text-sm text-center mb-4">{error}</p>}
            <button
              onClick={handleGenerate}
              disabled={isGenerateDisabled}
              className={`w-full text-white font-bold py-4 px-4 rounded-xl transition-all duration-300 text-lg
                ${isGenerateDisabled 
                  ? 'bg-pink-200 text-pink-400 cursor-not-allowed' 
                  : 'bg-pink-600 hover:bg-pink-700 shadow-lg hover:shadow-pink-500/50'
                }`}
            >
              {isLoading ? 'Đang tạo ảnh...' : 'Tạo 2 ảnh ngay'}
            </button>
          </div>
        </div>

        {/* Right Column: Results */}
        <div className="lg:col-span-2 flex flex-col gap-6">
          <ResultGrid 
            isLoading={isLoading} 
            images={generatedImages} 
            prompt={finalPrompt}
            numberOfImages={2}
          />
          <div className="text-center">
             <a 
                href="https://www.facebook.com/groups/808925604828645" 
                target="_blank" 
                rel="noopener noreferrer"
                className="inline-flex items-center gap-2 bg-blue-600 text-white text-xs font-bold py-2 px-4 rounded-full hover:bg-blue-700 transition-colors shadow-md"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="currentColor" viewBox="0 0 24 24"><path d="M9 8h-3v4h3v12h5v-12h3.642l.358-4h-4v-1.667c0-.955.192-1.333 1.115-1.333h2.885v-5h-3.808c-3.596 0-5.192 1.583-5.192 4.615v3.385z"/></svg>
                THAM GIA CỘNG ĐỒNG KOL AI GO GLOBAL
              </a>
          </div>
        </div>
      </main>
      <footer className="text-center p-4 text-pink-600 text-sm">
        <p>© 2024 App Ảnh Doanh Nhân - Sáng tạo bởi Phong Menly</p>
      </footer>
    </div>
  );
};

