import { GoogleGenAI, Modality } from "@google/genai";
import type { AspectRatio, GeneratedImage } from "../types";

interface GeneratePortraitsParams {
  prompt: string;
  negativePrompt: string;
  aspectRatio: AspectRatio;
  imageBase64: string;
  mimeType: string;
  numberOfImages: number;
  isFaceLockEnabled: boolean;
  withFlowers: boolean;
}

export const generatePortraits = async (params: GeneratePortraitsParams): Promise<GeneratedImage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faceLockInstruction = params.isFaceLockEnabled
    ? `It is absolutely CRITICAL and the HIGHEST PRIORITY to perfectly replicate the facial features, expression, and identity of the person in the provided photo. The face must be an exact match. Do not alter the person's identity.`
    : `Maintain the exact facial features, hair, and identity of the person from the original photo. Do not change the person's character in any way.`;

  const flowerInstruction = params.withFlowers
    ? `The subject is elegantly holding or positioned near a tasteful bouquet of flowers that enhances the professional and artistic aesthetic.`
    : `There are absolutely no flowers in the scene. Focus purely on the person and the environment.`;

  const compositionInstruction = `The framing is a medium portrait shot, specifically from mid-thigh up. This captures the person's pose, professional attire, and facial expression while showing the beautiful world-class background.`;

  const instructionPrompt = `Transform the person from the attached image into a professional business-class setting: "${params.prompt}". 
${faceLockInstruction}
${compositionInstruction}
${flowerInstruction}
The final image must be ultra-realistic, photorealistic, with perfect skin textures, natural lighting, and high-end photographic quality (Sony A7R IV, 85mm lens). Avoid any cartoonish or painterly effects.
Aspect ratio: ${params.aspectRatio}. 
Negative prompt: ${params.negativePrompt}.`;

  const numberOfImagesToGenerate = params.numberOfImages;

  const generationPromises = Array.from({ length: numberOfImagesToGenerate }, () =>
    ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: params.imageBase64,
              mimeType: params.mimeType,
            },
          },
          {
            text: instructionPrompt,
          },
        ],
      },
      config: {
        responseModalities: [Modality.IMAGE, Modality.TEXT],
      },
    })
  );

  const results = await Promise.allSettled(generationPromises);

  const generatedImages: GeneratedImage[] = [];
  let firstError: Error | null = null;

  results.forEach((result, i) => {
    if (result.status === 'fulfilled') {
      const response = result.value;
      const imagePart = response.candidates?.[0]?.content?.parts.find(part => part.inlineData);
      if (imagePart && imagePart.inlineData) {
        generatedImages.push({
          id: `gen-${i}-${new Date().getTime()}`,
          url: `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`,
          seed: Math.floor(Math.random() * 1000000).toString(),
        });
      }
    } else {
      if (!firstError) {
        const error = result.reason as Error;
        const message = error.message.toLowerCase();
        if (message.includes('safety')) {
            firstError = new Error("Yêu cầu bị chặn vì lý do an toàn. Thử ảnh hoặc mô tả khác.");
        } else {
          firstError = new Error(`Lỗi kết nối AI. Vui lòng thử lại.`);
        }
      }
    }
  });

  if (generatedImages.length === 0) {
    throw firstError || new Error("Không thể tạo ảnh. Vui lòng thử lại.");
  }

  return generatedImages;
};

