import { GoogleGenAI, Modality } from "@google/genai";
import type { AspectRatio, GeneratedImage } from "../types";

interface GeneratePortraitsParams {
  prompt: string;
  negativePrompt: string;
  aspectRatio: AspectRatio;
  imageBase64: string;
  mimeType: string;
  numberOfImages: number;
  isFaceLockEnabled: boolean;
  withFlowers: boolean;
  outfitMode: 'original' | 'suggested';
}

export const generatePortraits = async (params: GeneratePortraitsParams): Promise<GeneratedImage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Extremely strong instructions for identity preservation
  const identityInstruction = `
    STRICT REQUIREMENT: You MUST maintain 100% identical facial features, facial structure, skin tone, eye shape, nose shape, and mouth shape from the provided image. 
    The person in the generated image must be UNMISTAKABLY the same individual as in the source photo. 
    Do not generalize the face. Do not make the face look like a standard AI model. 
    Preserve the specific unique characteristics, ethnicity, and age of the person.
  `;

  const outfitInstruction = params.outfitMode === 'original'
    ? `IMPORTANT: Keep the EXACT original clothing, jewelry, and accessories from the source photo. Do not change her outfit at all. Only change the background and environment to match the concept: "${params.prompt}".`
    : `CLOTHING: Replace her original clothes with a high-fashion, seductive, and glamorous outfit that perfectly suits the concept: "${params.prompt}". The new outfit should be premium, elegant, and alluring.`;

  const flowerInstruction = params.withFlowers
    ? `Enhancement: The girl is elegantly holding or surrounded by beautiful premium flowers that complement the scene.`
    : `Restriction: No flowers should be present in the scene.`;

  const compositionInstruction = `Framing: Medium portrait shot from mid-thigh up. Professional photography, sharp focus on the subject, beautiful bokeh in the background.`;

  const instructionPrompt = `
    Transform this person according to this theme: "${params.prompt}".
    ${identityInstruction}
    ${outfitInstruction}
    ${compositionInstruction}
    ${flowerInstruction}
    Quality: Ultra-realistic, 8k resolution, photorealistic, cinematic lighting, masterwork. 
    Avoid: cartoon, painting, 3d render, distorted face, changed identity.
  `;

  const generationPromises = Array.from({ length: params.numberOfImages }, () =>
    ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: params.imageBase64,
              mimeType: params.mimeType,
            },
          },
          {
            text: instructionPrompt,
          },
        ],
      },
      config: {
        responseModalities: [Modality.IMAGE, Modality.TEXT],
      },
    })
  );

  const results = await Promise.allSettled(generationPromises);
  const generatedImages: GeneratedImage[] = [];
  let firstError: Error | null = null;

  results.forEach((result, i) => {
    if (result.status === 'fulfilled') {
      const response = result.value;
      const imagePart = response.candidates?.[0]?.content?.parts.find(part => part.inlineData);
      if (imagePart && imagePart.inlineData) {
        generatedImages.push({
          id: `gen-${i}-${new Date().getTime()}`,
          url: `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`,
          seed: Math.floor(Math.random() * 1000000).toString(),
        });
      }
    } else {
      if (!firstError) {
        firstError = result.reason as Error;
      }
    }
  });

  if (generatedImages.length === 0) {
    throw firstError || new Error("Không thể họa nét nàng lúc này. Vui lòng thử lại.");
  }

  return generatedImages;
};

import React, { useCallback, useState } from 'react';
import ImageCropperModal from './ImageCropperModal';

interface ImageUploaderProps {
  onImageUpload: (file: File, previewUrl: string) => void;
  preview: string | null;
  isFaceLockEnabled: boolean;
  onToggleFaceLock: (enabled: boolean) => void;
  withFlowers: boolean;
  onToggleWithFlowers: (enabled: boolean) => void;
  outfitMode: 'original' | 'suggested';
  onOutfitModeChange: (mode: 'original' | 'suggested') => void;
}

const ImageUploader: React.FC<ImageUploaderProps> = ({ 
  onImageUpload, 
  preview, 
  isFaceLockEnabled, 
  onToggleFaceLock,
  withFlowers,
  onToggleWithFlowers,
  outfitMode,
  onOutfitModeChange
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const [imageToCrop, setImageToCrop] = useState<{file: File, url: string} | null>(null);

  const handleFileChange = (files: FileList | null) => {
    if (files && files.length > 0) {
      const file = files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setImageToCrop({ file, url: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCropComplete = (croppedFile: File, previewUrl: string) => {
    onImageUpload(croppedFile, previewUrl);
    setImageToCrop(null);
  };

  const handleUseOriginal = () => {
      if (imageToCrop) {
        onImageUpload(imageToCrop.file, imageToCrop.url);
        setImageToCrop(null);
      }
  };

  const triggerFileInput = () => document.getElementById('file-input')?.click();

  return (
    <div className="glass-card p-6 rounded-3xl shadow-xl text-zinc-900 border-pink-100">
      {imageToCrop && (
        <ImageCropperModal
          isOpen={!!imageToCrop}
          onClose={() => setImageToCrop(null)}
          imgSrc={imageToCrop.url}
          onConfirm={handleCropComplete}
          onUseOriginal={handleUseOriginal}
        />
      )}

      <h2 className="text-xl font-playfair font-bold mb-4 text-rose-600">1. Đưa chân dung nàng lên</h2>

      <div 
        className={`relative flex flex-col items-center justify-center p-8 border-2 border-dashed rounded-2xl transition-all duration-500 ${isDragging ? 'border-pink-500 bg-pink-50/50 scale-[0.98]' : 'border-pink-200 bg-white/50 hover:border-pink-300'} ${!preview ? 'cursor-pointer' : ''}`}
        onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
        onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
        onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFileChange(e.dataTransfer.files); }}
        onClick={!preview ? triggerFileInput : undefined}
      >
        <input 
          type="file" 
          id="file-input" 
          className="hidden" 
          accept="image/*"
          onChange={(e) => { handleFileChange(e.target.files); e.target.value = ''; }}
        />
        {preview ? (
          <div className="flex flex-col items-center text-center">
            <img src={preview} alt="Nàng" className="max-h-60 w-auto rounded-xl object-contain shadow-2xl mb-4 border-4 border-white" />
            <button onClick={triggerFileInput} className="text-xs font-bold text-rose-500 hover:text-rose-600 bg-white px-4 py-2 rounded-full shadow-md transition-all">
                Đổi ảnh khác
            </button>
          </div>
        ) : (
          <div className="text-center">
            <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg className="h-8 w-8 text-rose-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <p className="text-sm font-medium text-zinc-600">Chọn ảnh chân dung rõ mặt</p>
            <p className="mt-1 text-xs text-rose-300">Nàng sẽ đẹp hơn với ảnh đủ sáng</p>
          </div>
        )}
      </div>

      <div className="mt-6 space-y-4">
        {/* Identity Lock Status */}
        <div className="flex items-center justify-between p-3 bg-white/50 rounded-xl border border-pink-50">
           <span className="text-sm font-bold text-rose-500">BẢO VỆ DIỆN MẠO (100%)</span>
           <div className="w-4 h-4 rounded-full bg-green-500 animate-pulse shadow-green-200 shadow-lg"></div>
        </div>

