import { GoogleGenAI, Modality } from "@google/genai";
import type { AspectRatio, GeneratedImage } from "../types";

interface GeneratePortraitsParams {
  prompt: string;
  negativePrompt: string;
  aspectRatio: AspectRatio;
  imageBase64: string;
  mimeType: string;
  numberOfImages: number;
  isFaceLockEnabled: boolean;
  withFlowers: boolean;
  outfitMode: 'original' | 'suggested';
}

export const generatePortraits = async (params: GeneratePortraitsParams): Promise<GeneratedImage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // 100% Authenticity and Emotion Identity Preservation
  const identityInstruction = `
    ABSOLUTE REQUIREMENT: 100% identical facial features. This is a RAW PHOTOGRAPH, not a digital render.
    - Preserve every detail: skin pores, fine lines, unique eye shape, and the exact facial structure of the person in the source.
    - The subject MUST make direct, soulful eye contact with the camera, creating an intimate and emotional connection with the viewer.
    - Expression should be authentic, candid, and full of emotion (a warm smile, a thoughtful gaze, or a confident look).
  `;

  const framingInstruction = `
    COMPOSITION: This is a medium-full "hip-up" portrait (captured from the hips/buttocks upwards). 
    - The person should be the central focus, filling the frame elegantly while showing enough of the world-famous background to establish the location.
    - Use an 85mm f/1.8 lens effect for a natural depth of field, making the background beautifully soft (bokeh) but recognizable.
  `;

  const outfitInstruction = params.outfitMode === 'original'
    ? `OUTFIT: Keep the EXACT clothing and accessories from the source photo. No changes.`
    : `OUTFIT: Change her clothing to a premium, natural, and alluring style that fits the location: "${params.prompt}". The fabric should look real (silk, linen, or high-end wool) with natural folds.`;

  const qualityInstruction = `
    REALISM SPECS: High-end DSLR photography, raw photo, natural sunlight, soft shadows, 8k resolution, highly detailed skin texture, no retouching, realistic hair strands.
  `;

  const instructionPrompt = `
    ${identityInstruction}
    ${framingInstruction}
    ${outfitInstruction}
    Location & Context: "${params.prompt}".
    ${params.withFlowers ? "The girl is holding a natural bouquet that looks freshly picked." : "No flowers."}
    ${qualityInstruction}
    Negative: plastic, cartoon, anime, 3d render, airbrushed, smooth skin, fake, distorted, westernized, changed identity, full body, headshot only.
  `;

  const generationPromises = Array.from({ length: params.numberOfImages }, () =>
    ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: params.imageBase64, mimeType: params.mimeType } },
          { text: instructionPrompt }
        ],
      },
      config: { responseModalities: [Modality.IMAGE, Modality.TEXT] },
    })
  );

  const results = await Promise.allSettled(generationPromises);
  const generatedImages: GeneratedImage[] = [];
  let firstError: Error | null = null;

  results.forEach((result, i) => {
    if (result.status === 'fulfilled') {
      const response = result.value;
      const imagePart = response.candidates?.[0]?.content?.parts.find(part => part.inlineData);
      if (imagePart?.inlineData) {
        generatedImages.push({
          id: `gen-${i}-${Date.now()}`,
          url: `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`,
          seed: Math.floor(Math.random() * 1000000).toString(),
        });
      }
    } else {
      firstError = firstError || (result.reason as Error);
    }
  });

  if (generatedImages.length === 0) throw firstError || new Error("Lỗi kết nối.");
  return generatedImages;
};

