import { GoogleGenAI, Modality } from "@google/genai";
import type { AspectRatio, GeneratedImage } from "../types";

interface GeneratePortraitsParams {
  prompt: string;
  negativePrompt: string;
  aspectRatio: AspectRatio;
  imageBase64: string;
  mimeType: string;
  numberOfImages: number;
  isFaceLockEnabled: boolean;
  withFlowers: boolean;
}

export const generatePortraits = async (params: GeneratePortraitsParams): Promise<GeneratedImage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // 100% Face Identity Preservation & Real Natural Scenery
  const identityInstruction = `
    ABSOLUTE REQUIREMENT: 100% identical facial features. This is a RAW PHOTOGRAPH captured by a professional.
    - FACE: Lock the exact facial structure, eyes, nose, and lips of the person in the source image.
    - POSE: Natural, attractive "check-in" pose. She should look like a real traveler capturing a memory. Effortless, graceful, and interactive with the environment (e.g., lightly touching a flower, or a soft candid turn).
    - EMOTION: Create a deep emotional connection. The subject's eyes must be soulful and expressive, looking directly at the camera with a warm, authentic feeling.
  `;

  const sceneryInstruction = `
    SCENERY: 100% REAL FLOWERS AND NATURAL LANDSCAPES. 
    - The environment must look like a real, world-famous location. 
    - Flowers must have realistic textures: petals with dew, natural imperfections, and organic growth. 
    - No plastic-looking plants, no fake digital bokeh. 
    - Shot on high-end camera (Sony A7R IV) with a prime 85mm lens for natural, creamy background blur.
  `;

  const framingInstruction = `
    COMPOSITION: Hip-up portrait (captured from the hips/buttocks upwards). 
    - The subject is the heart of the image, filling the frame in a flattering way.
  `;

  const qualityInstruction = `
    REALISM SPECS: Photorealistic RAW photo. Visible skin texture, natural pores, realistic hair, soft sunlight. 100% authenticity.
  `;

  const instructionPrompt = `
    ${identityInstruction}
    ${sceneryInstruction}
    ${framingInstruction}
    Check-in Scenario: "${params.prompt}".
    ${qualityInstruction}
    Negative: fake flowers, plastic plants, cartoon, anime, 3d render, airbrushed, smooth skin, changed identity, headshot only, full body, stiff pose, distorted face.
  `;

  const generationPromises = Array.from({ length: params.numberOfImages }, () =>
    ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data: params.imageBase64, mimeType: params.mimeType } },
          { text: instructionPrompt }
        ],
      },
      config: { responseModalities: [Modality.IMAGE, Modality.TEXT] },
    })
  );

  const results = await Promise.allSettled(generationPromises);
  const generatedImages: GeneratedImage[] = [];
  let firstError: Error | null = null;

  results.forEach((result, i) => {
    if (result.status === 'fulfilled') {
      const response = result.value;
      const imagePart = response.candidates?.[0]?.content?.parts.find(part => part.inlineData);
      if (imagePart?.inlineData) {
        generatedImages.push({
          id: `gen-${i}-${Date.now()}`,
          url: `data:${imagePart.inlineData.mimeType};base64,${imagePart.inlineData.data}`,
          seed: Math.floor(Math.random() * 1000000).toString(),
        });
      }
    } else {
      firstError = firstError || (result.reason as Error);
    }
  });

  if (generatedImages.length === 0) throw firstError || new Error("AI không phản hồi.");
  return generatedImages;
};

import React, { useState, useRef } from 'react';
import ReactCrop, { type Crop, type PixelCrop, centerCrop, makeAspectCrop } from 'react-image-crop';

interface ImageCropperModalProps {
  isOpen: boolean;
  onClose: () => void;
  imgSrc: string;
  onConfirm: (file: File, url: string) => void;
  onUseOriginal: () => void;
}

const aspectRatios = [
    { value: 0.75, label: 'Dọc chuẩn (0.75)' }, // 3:4
    { value: 9 / 16, label: 'Dọc Story (9:16)' },
    { value: 1 / 1, label: 'Vuông' },
    { value: undefined, label: 'Tự do' },
];

function getCroppedImg(image: HTMLImageElement, crop: PixelCrop, fileName: string): Promise<{file: File, url: string}> {
  const canvas = document.createElement('canvas');
  const scaleX = image.naturalWidth / image.width;
  const scaleY = image.naturalHeight / image.height;

  canvas.width = crop.width * scaleX;
  canvas.height = crop.height * scaleY;
  const ctx = canvas.getContext('2d');

  if (!ctx) {
    return Promise.reject(new Error('Could not get canvas context'));
  }

  ctx.drawImage(
    image,
    crop.x * scaleX,
    crop.y * scaleY,
    crop.width * scaleX,
    crop.height * scaleY,
    0,
    0,
    canvas.width,
    canvas.height
  );

  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => {
        if (!blob) {
          reject(new Error('Canvas is empty'));
          return;
        }
        const file = new File([blob], fileName, { type: 'image/jpeg' });
        const url = URL.createObjectURL(blob);
        resolve({ file, url });
      },
      'image/jpeg',
      0.95
    );
  });
}

const ImageCropperModal: React.FC<ImageCropperModalProps> = ({ isOpen, onClose, imgSrc, onConfirm, onUseOriginal }) => {
  // Mặc định là 0.75 (3:4)
  const [aspect, setAspect] = useState<number | undefined>(0.75);
  const [crop, setCrop] = useState<Crop>();
  const [completedCrop, setCompletedCrop] = useState<PixelCrop>();
  const imgRef = useRef<HTMLImageElement>(null);

  function onImageLoad(e: React.SyntheticEvent<HTMLImageElement>) {
    const { width, height } = e.currentTarget;
    const initialAspect = 0.75;
    const newCrop = centerCrop(
        makeAspectCrop(
            {
                unit: '%',
                width: 80,
            },
            initialAspect,
            width,
            height
        ),
        width,
        height
    );
    setCrop(newCrop);
    setCompletedCrop(newCrop);
  }

  const handleConfirmCrop = async () => {
    if (completedCrop && imgRef.current) {
        try {
            const {file, url} = await getCroppedImg(imgRef.current, completedCrop, 'cropped-beauty.jpg');
            onConfirm(file, url);
        } catch (e) {
            console.error(e);
            alert("Không thể cắt ảnh, vui lòng thử lại.");
        }
    } else {
        alert("Vui lòng chọn vùng ảnh.");
    }
  }

  const handleSetAspect = (newAspect: number | undefined) => {
      setAspect(newAspect);
      if (imgRef.current) {
        const { width, height } = imgRef.current;
        const newCrop = centerCrop(
            makeAspectCrop(
                {
                    unit: '%',
                    width: 80,
                },
                newAspect || width / height,
                width,
                height
            ),
            width,
            height
        );
        setCrop(newCrop);
        setCompletedCrop(newCrop);
      }
  }

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-zinc-900/90 backdrop-blur-sm flex items-center justify-center z-[110] p-4">
      <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-2xl flex flex-col overflow-hidden border border-white/20">
        <div className="p-6 border-b border-pink-50 flex justify-between items-center bg-white">
            <h3 className="text-xl font-playfair font-bold text-rose-600">Họa nét khung hình</h3>
            <button onClick={onClose} className="p-2 hover:bg-rose-50 rounded-full text-rose-300 transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
        </div>

        <div className="flex-grow min-h-0 bg-[#fff5f7] p-4 flex items-center justify-center">
           {imgSrc && (
             <ReactCrop
                crop={crop}
                onChange={(_, percentCrop) => setCrop(percentCrop)}
                onComplete={(c) => setCompletedCrop(c)}
                aspect={aspect}
                className="max-h-[50vh] shadow-lg rounded-lg overflow-hidden"
            >
                <img ref={imgRef} alt="Crop" src={imgSrc} onLoad={onImageLoad} style={{ maxHeight: '50vh', objectFit: 'contain' }} className="allow-context-menu"/>
            </ReactCrop>
           )}
        </div>

        <div className="p-6 bg-white space-y-6">
            <div className="flex flex-wrap justify-center gap-2">
                {aspectRatios.map(ar => (
                    <button
                        key={ar.label}
                        onClick={() => handleSetAspect(ar.value)}
                        className={`px-4 py-2 text-[10px] font-bold uppercase tracking-wider rounded-full border-2 transition-all duration-300
                            ${aspect === ar.value ? 'bg-rose-500 border-rose-500 text-white shadow-md scale-105' : 'bg-white border-pink-100 text-rose-300 hover:border-rose-300'}
                        `}
                    >
                        {ar.label}
                    </button>
                ))}
            </div>

            <div className="flex flex-col sm:flex-row gap-3">
                <button 
                    onClick={onUseOriginal} 
                    className="flex-1 bg-white border-2 border-rose-100 text-rose-400 font-bold py-4 px-6 rounded-2xl hover:bg-rose-50 transition-all duration-300 active:scale-95 shadow-sm"
                >
                    DÙNG ẢNH GỐC
                </button>
                <button 
                    onClick={handleConfirmCrop} 
                    className="flex-[1.5] bg-gradient-to-r from-rose-500 to-pink-500 text-white font-bold py-4 px-6 rounded-2xl hover:shadow-xl hover:shadow-rose-100 transition-all duration-500 active:scale-95 shadow-lg border-b-4 border-rose-700"
                >
                    XÁC NHẬN KHUNG HÌNH
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

